#include <vector>
#include <iostream>

int main() {
    std::vector<int> vec{1, 2, 3};
    typedef std::vector<int>::iterator VecIterator;  // Typedef for the container's iterator
    typedef std::vector<int>::const_iterator ConstVecIterator;  // Typedef for the const iterator

    VecIterator it = vec.begin();  // Compiler resolves VecIterator to the actual iterator type
    *it = 10;  // Modifies the element via non-const iterator

    ConstVecIterator constIt = vec.cbegin();  // Compiler ensures constIt provides read-only access
    // int value = *constIt;  // This would work, but assignment like *constIt = 20; would fail at compile time

    std::cout << *it << std::endl;  // Output: 10
    return 0;
}
